1	import "server-only";
2	import { generateJSON } from "@tiptap/html/server";
3	import type { JSONContent } from "@tiptap/react";
4	import mammoth from "mammoth";
5	import { marked } from "marked";
6	
7	import { editorExtensions } from "@/lib/editor/extensions";
8	
9	export const MAX_IMPORT_BYTES = 4 * 1024 * 1024;
10	
11	const KINDS = { docx: "docx", markdown: "md", md: "md", txt: "txt" } as const;
12	type Kind = (typeof KINDS)[keyof typeof KINDS];
13	
14	export class ImportError extends Error {
15	  override name = "ImportError";
16	}
17	
18	const extensionOf = (fileName: string) =>
19	  fileName.includes(".") ? (fileName.split(".").pop() ?? "").toLowerCase() : "";
20	
21	const detectKind = (fileName: string): Kind => {
22	  const ext = extensionOf(fileName);
23	  if (ext in KINDS) {
24	    return KINDS[ext as keyof typeof KINDS];
25	  }
26	  if (ext === "doc") {
27	    throw new ImportError(
28	      "Old .doc files aren't supported. Save it as .docx in Word and try again."
29	    );
30	  }
31	  if (ext === "pdf") {
32	    throw new ImportError(
33	      "PDFs aren't supported. Upload a .docx, .md or .txt file instead."
34	    );
35	  }
36	  throw new ImportError(
37	    "That file type isn't supported. Upload a .docx, .md or .txt file."
38	  );
39	};
40	
41	/** File name without its extension, used as the new document's title. */
42	export const titleFromFileName = (fileName: string) => {
43	  const base = fileName.replace(/\.[^.]+$/u, "").trim();
44	  return base || "Untitled";
45	};
46	
47	// Word styles mammoth does not map by default. Underline is ignored by
48	// mammoth unless mapped explicitly.
49	const DOCX_STYLE_MAP = [
50	  "u => u",
51	  "p[style-name='Title'] => h1:fresh",
52	  "p[style-name='Subtitle'] => h2:fresh",
53	];
54	
55	const escapeHtml = (text: string) =>
56	  text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
57	
58	const toHtml = async (kind: Kind, buffer: Buffer): Promise<string> => {
59	  switch (kind) {
60	    case "docx": {
61	      try {
62	        const result = await mammoth.convertToHtml(
63	          { buffer },
64	          {
65	            // Keep a placeholder so images can be counted, without inlining
66	            // their bytes as base64.
67	            convertImage: mammoth.images.imgElement(() =>
68	              Promise.resolve({ src: "" })
69	            ),
70	            styleMap: DOCX_STYLE_MAP,
71	          }
72	        );
73	        return result.value;
74	      } catch {
75	        throw new ImportError(
76	          "This .docx file couldn't be read. It may be damaged or password-protected."
77	        );
78	      }
79	    }
80	    case "md": {
81	      return marked.parse(buffer.toString("utf-8"), {
82	        async: false,
83	        gfm: true,
84	      });
85	    }
86	    default: {
87	      return buffer
88	        .toString("utf-8")
89	        .replaceAll("\r\n", "\n")
90	        .trim()
91	        .split(/\n\s*\n/u)
92	        .map((block) => `<p>${escapeHtml(block).replaceAll("\n", "<br>")}</p>`)
93	        .join("");
94	    }
95	  }
96	};
97	
98	const count = (html: string, tag: string) =>
99	  (html.match(new RegExp(`<${tag}[\\s>/]`, "giu")) ?? []).length;
100	
101	const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;
102	
103	export interface ImportResult {
104	  title: string;
105	  content: JSONContent;
106	  /** Human-readable notes about content the editor could not keep. */
107	  removed: string[];
108	}
109	
110	export const convertUpload = async (file: File): Promise<ImportResult> => {
111	  if (file.size === 0) {
112	    throw new ImportError("That file is empty.");
113	  }
114	  if (file.size > MAX_IMPORT_BYTES) {
115	    throw new ImportError("That file is larger than 4 MB.");
116	  }
117	
118	  const kind = detectKind(file.name);
119	  const buffer = Buffer.from(await file.arrayBuffer());
120	  let html = await toHtml(kind, buffer);
121	
122	  const removed: string[] = [];
123	  const images = count(html, "img");
124	  const tables = count(html, "table");
125	  if (images > 0) {
126	    removed.push(`${plural(images, "image")} removed`);
127	  }
128	  if (tables > 0) {
129	    removed.push(`${plural(tables, "table")} converted to plain text`);
130	  }
131	
132	  html = html
133	    // The editor has three heading levels; fold deeper ones into the third.
134	    .replaceAll(/<(?<slash>\/?)h[4-6]\b/giu, "<$<slash>h3")
135	    // Images are not kept; drop them and any paragraph left empty by that.
136	    .replaceAll(/<img\b[^>]*>/giu, "")
137	    .replaceAll(/<p>\s*<\/p>/giu, "");
138	
139	  // Parsing against the editor schema drops every element and attribute it
140	  // does not define (scripts, styles, links, colours), keeping their text.
141	  const content = generateJSON(html, editorExtensions);
142	
143	  return { content, removed, title: titleFromFileName(file.name) };
144	};
